 1→import { useState } from 'react';
 2→import type { TableInfo } from '../types';
 3→import './Sidebar.css';
 4→
 5→interface SidebarProps {
 6→  tables: TableInfo[];
 7→  onTableClick: (tableName: string) => void;
 8→  onTableDelete: (tableName: string) => void;
 9→  collapsed: boolean;
10→}
11→
12→export function Sidebar({ tables, onTableClick, onTableDelete, collapsed }: SidebarProps) {
13→  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
14→
15→  const toggle = (name: string) => {
16→    setExpanded((prev) => ({ ...prev, [name]: !prev[name] }));
17→  };
18→
19→  return (
20→    <div className={`sidebar ${collapsed ? 'sidebar--collapsed' : ''}`}>
21→      <h3 className="sidebar__title">Tables</h3>
22→      {tables.length === 0 && (
23→        <p className="sidebar__empty">No tables yet. Upload a CSV to get started.</p>
24→      )}
25→      <ul className="sidebar__list">
26→        {tables.map((table) => (
27→          <li key={table.name} className="sidebar__item">
28→            <div className="sidebar__table-header">
29→              <button
30→                className="sidebar__toggle"
31→                onClick={() => toggle(table.name)}
32→              >
33→                {expanded[table.name] ? '\u25BC' : '\u25B6'}
34→              </button>
35→              <button
36→                className="sidebar__table-name"
37→                onClick={() => onTableClick(table.name)}
38→                title={`SELECT * FROM "${table.name}" LIMIT 100`}
39→              >
40→                {table.name}
41→              </button>
42→              <span className="sidebar__row-count">
43→                {table.rowCount} row{table.rowCount !== 1 ? 's' : ''}
44→              </span>
45→              <button
46→                className="sidebar__delete"
47→                onClick={(e) => {
48→                  e.stopPropagation();
49→                  onTableDelete(table.name);
50→                }}
51→                title={`Delete table "${table.name}"`}
52→                aria-label={`Delete table ${table.name}`}
53→              >
54→                🗑
55→              </button>
56→            </div>
57→            {expanded[table.name] && (
58→              <ul className="sidebar__columns">
59→                {table.columns.map((col) => (
60→                  <li key={col.name} className="sidebar__column">
61→                    <span className="sidebar__col-name">{col.name}</span>
62→                    <span className="sidebar__col-type">{col.type}</span>
63→                  </li>
64→                ))}
65→              </ul>
66→            )}
67→          </li>
68→        ))}
69→      </ul>
70→    </div>
71→  );
72→}
