.sidebar {
  background: #e9ecef;
  border-right: 1px solid #ddd;
  padding: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100vh;
}

.sidebar--collapsed {
  border-right: 1px solid #ddd;
  width: 44px;
  min-width: 44px;
}

.sidebar__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: #e9ecef;
  border-bottom: 1px solid #ddd;
  flex-shrink: 0;
  position: sticky;
  top: 0;
  z-index: 1;
}

.sidebar--collapsed .sidebar__header {
  justify-content: center;
  padding: 8px;
  border-bottom: none;
}

.sidebar__title {
  margin: 0;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #666;
}

.sidebar--collapsed .sidebar__title {
  display: none;
}

.sidebar--collapsed .sidebar__empty,
.sidebar--collapsed .sidebar__list {
  display: none;
}

.sidebar__collapse-toggle {
  background: none;
  border: none;
  cursor: pointer;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  flex-shrink: 0;
}

.sidebar__collapse-toggle:hover {
  background: #e8e8e8;
}

.sidebar__hamburger {
  display: block;
  width: 16px;
  height: 2px;
  background: #666;
  position: relative;
}

.sidebar__hamburger::before,
.sidebar__hamburger::after {
  content: '';
  display: block;
  width: 16px;
  height: 2px;
  background: #666;
  position: absolute;
  left: 0;
}

.sidebar__hamburger::before {
  top: -5px;
}

.sidebar__hamburger::after {
  top: 5px;
}

.sidebar__empty {
  font-size: 13px;
  color: #999;
}

.sidebar__list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.sidebar__item {
  margin-bottom: 4px;
}

.sidebar__table-header {
  display: flex;
  align-items: center;
  gap: 4px;
}

.sidebar__toggle {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 10px;
  padding: 2px 4px;
  color: #666;
}

.sidebar__table-name {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  color: #333;
  padding: 2px 4px;
  border-radius: 3px;
  text-align: left;
}

.sidebar__table-name:hover {
  background: #e8e8e8;
}

.sidebar__row-count {
  font-size: 11px;
  color: #999;
  margin-left: auto;
}

.sidebar__delete {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 12px;
  padding: 2px 4px;
  border-radius: 3px;
  opacity: 0;
  transition: opacity 0.15s;
  line-height: 1;
}

.sidebar__delete:hover {
  background: #fee;
}

.sidebar__table-header:hover .sidebar__delete {
  opacity: 1;
}

.sidebar__columns {
  list-style: none;
  padding: 4px 0 4px 24px;
  margin: 0;
}

.sidebar__column {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  padding: 2px 0;
}

.sidebar__col-name {
  color: #333;
}

.sidebar__col-type {
  color: #999;
  font-style: italic;
}

